@namespace sv_0974923068dc45e09f12567adabe83ef.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
                <button class="nav-link @(section == ActiveSection ? "active" : "")"
                        @onclick="() => OnSectionChanged.InvokeAsync(section)">
                    <span class="sidebar-icon">@GetIcon(section)</span>
                    @section
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_0974923068dc45e09f12567adabe83ef.Components.Pages.Settings
@using sv_0974923068dc45e09f12567adabe83ef.Services

<div class="settings-section">
    <h3>Profile</h3>

    @if (Profile is not null)
    {
        <div class="profile-content">
            <div class="avatar-preview mb-3">
                <img src="@editDisplayAvatarUrl" alt="Avatar" class="rounded-circle" width="100" height="100" />
                <p class="text-muted mt-1 small">@editDisplayAvatarUrl</p>
            </div>

            <div class="mb-3">
                <label class="form-label">Display Name</label>
                <input type="text" class="form-control" @bind="editDisplayName" />
            </div>

            <div class="mb-3">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="editEmail" />
            </div>

            <div class="mb-3">
                <label class="form-label">Bio</label>
                <textarea class="form-control" rows="3" @bind="editBio"></textarea>
            </div>

            <div class="d-flex gap-2">
                <button class="btn btn-primary" @onclick="SaveAsync">Save Changes</button>
                <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
            </div>

            @if (showSuccess)
            {
                <div class="alert alert-success mt-3" role="alert">Profile saved successfully!</div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string editDisplayName = "";
    private string editEmail = "";
    private string editDisplayAvatarUrl = "";
    private string editBio = "";
    private bool showSuccess;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !hasInitialized)
        {
            LoadFromProfile();
            hasInitialized = true;
        }
    }

    private bool hasInitialized;

    private void LoadFromProfile()
    {
        editDisplayName = Profile!.DisplayName;
        editEmail = Profile.Email;
        editDisplayAvatarUrl = Profile.AvatarUrl;
        editBio = Profile.Bio;
    }

    private async Task SaveAsync()
    {
        var updated = new UserProfile(editDisplayName, editEmail, editDisplayAvatarUrl, editBio);
        await OnSave.InvokeAsync(updated);
        showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void Discard()
    {
        LoadFromProfile();
        showSuccess = false;
    }
}

@namespace sv_0974923068dc45e09f12567adabe83ef.Components.Pages.Settings
@using sv_0974923068dc45e09f12567adabe83ef.Services

<div class="settings-section">
    <h3>Notifications</h3>

    @if (Prefs is not null)
    {
        <div class="mb-4">
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="emailNotifications" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="pushNotifications" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="weeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>
        </div>

        <h5>Muted Channels</h5>
        <div class="mb-3">
            @foreach (var channel in allChannels)
            {
                <div class="form-check mb-1">
                    <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                           checked="@mutedChannels.Contains(channel)"
                           @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                    <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                </div>
            }
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>

        @if (showSuccess)
        {
            <div class="alert alert-success mt-3" role="alert">Preferences saved!</div>
        }
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private bool showSuccess;

    private static readonly string[] allChannels = { "general", "marketing", "engineering", "design", "announcements" };

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !hasInitialized)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = new HashSet<string>(Prefs.MutedChannels);
            hasInitialized = true;
        }
    }

    private bool hasInitialized;

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted) mutedChannels.Add(channel);
        else mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_0974923068dc45e09f12567adabe83ef.Components.Pages.Settings
@using sv_0974923068dc45e09f12567adabe83ef.Services

<div class="settings-section">
    <h3>Security</h3>

    @if (Settings is not null)
    {
        <!-- Change Password Panel -->
        <div class="card mb-4">
            <div class="card-header d-flex justify-content-between align-items-center"
                 style="cursor: pointer" @onclick="() => passwordExpanded = !passwordExpanded">
                <span>Change Password</span>
                <span>@(passwordExpanded ? "▼" : "▶")</span>
            </div>
            @if (passwordExpanded)
            {
                <div class="card-body">
                    <div class="mb-2">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="currentPassword" />
                    </div>
                    <div class="mb-2">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm Password</label>
                        <input type="password" class="form-control" @bind="confirmPassword" />
                    </div>
                    @if (!string.IsNullOrEmpty(passwordError))
                    {
                        <div class="alert alert-danger">@passwordError</div>
                    }
                    @if (passwordSuccess)
                    {
                        <div class="alert alert-success">Password updated successfully!</div>
                    }
                    <button class="btn btn-primary" @onclick="ChangePasswordAsync">Update Password</button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="card mb-4">
            <div class="card-body">
                <div class="d-flex align-items-center justify-content-between">
                    <div>
                        <h5 class="mb-1">Two-Factor Authentication</h5>
                        <span class="badge @(Settings.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                            @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" checked="@Settings.TwoFactorEnabled"
                               @onchange="Toggle2FA" />
                    </div>
                </div>
                @if (Settings.LastPasswordChange.HasValue)
                {
                    <p class="text-muted small mt-2 mb-0">
                        Last password change: @Settings.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                    </p>
                }
            </div>
        </div>

        <!-- Active Sessions -->
        <div class="card mb-4">
            <div class="card-header">Active Sessions</div>
            <div class="card-body p-0">
                <table class="table table-hover mb-0">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in Settings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (session.Id != CurrentSessionId)
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="badge bg-info">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (sessionToRevoke is not null)
        {
            <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
                <div class="modal-dialog">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">Revoke Session</h5>
                            <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                        </div>
                        <div class="modal-body">
                            <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> from <strong>@sessionToRevoke.Location</strong>?</p>
                        </div>
                        <div class="modal-footer">
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                            <button class="btn btn-danger" @onclick="ConfirmRevokeAsync">Revoke Session</button>
                        </div>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string current, string newPw)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter] public EventCallback<bool> OnToggle2FA { get; set; }

    private string CurrentSessionId => Settings?.Sessions.FirstOrDefault()?.Id ?? "";

    private bool passwordExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private bool passwordSuccess;

    private ActiveSession? sessionToRevoke;

    private async Task ChangePasswordAsync()
    {
        passwordError = null;
        passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All fields are required.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((currentPassword, newPassword));
        passwordSuccess = true;
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
    }

    private async Task Toggle2FA(ChangeEventArgs e)
    {
        var enabled = (bool)e.Value!;
        await OnToggle2FA.InvokeAsync(enabled);
    }

    private void PromptRevoke(ActiveSession session) => sessionToRevoke = session;
    private void CancelRevoke() => sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(sessionToRevoke.Id);
            sessionToRevoke = null;
        }
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

@namespace sv_0974923068dc45e09f12567adabe83ef.Components.Pages.Settings
@using sv_0974923068dc45e09f12567adabe83ef.Services

<div class="settings-section">
    <h3>Appearance</h3>

    @if (Settings is not null)
    {
        <!-- Theme -->
        <div class="mb-4">
            <h5>Theme</h5>
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                           value="@theme" checked="@(selectedTheme == theme)"
                           @onchange="() => selectedTheme = theme" />
                    <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                </div>
            }
        </div>

        <!-- Font Size -->
        <div class="mb-4">
            <h5>Font Size</h5>
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                           value="@size" checked="@(selectedFontSize == size)"
                           @onchange="() => selectedFontSize = size" />
                    <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                </div>
            }
        </div>

        <!-- Language -->
        <div class="mb-4">
            <h5>Language</h5>
            <select class="form-select" @bind="selectedLanguage">
                <option value="English">English</option>
                <option value="Spanish">Spanish</option>
                <option value="French">French</option>
                <option value="German">German</option>
                <option value="Japanese">Japanese</option>
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="mb-4">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
                <label class="form-check-label" for="compactMode">Compact Mode</label>
            </div>
        </div>

        <!-- Live Preview -->
        <div class="mb-4">
            <h5>Preview</h5>
            <div class="appearance-preview @GetPreviewClasses()" style="@GetPreviewStyles()">
                <h6>Sample Heading</h6>
                <p>This is how your content will look with the selected settings.</p>
                <button class="btn btn-sm btn-primary">Sample Button</button>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync">Save</button>

        @if (showSuccess)
        {
            <div class="alert alert-success mt-3" role="alert">Appearance settings saved!</div>
        }
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "English";
    private bool compactMode;
    private bool showSuccess;
    private bool hasInitialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !hasInitialized)
        {
            selectedTheme = Settings.Theme;
            selectedFontSize = Settings.FontSize;
            selectedLanguage = Settings.Language;
            compactMode = Settings.CompactMode;
            hasInitialized = true;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string> { "border", "rounded", "p-3" };
        if (compactMode) classes.Add("compact");
        return string.Join(" ", classes);
    }

    private string GetPreviewStyles()
    {
        var bg = selectedTheme == "Dark" ? "#1e1e1e" : "#ffffff";
        var color = selectedTheme == "Dark" ? "#e0e0e0" : "#212529";
        var fontSize = selectedFontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        var padding = compactMode ? "0.5rem" : "1rem";

        return $"background-color: {bg}; color: {color}; font-size: {fontSize}; padding: {padding};";
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await OnSave.InvokeAsync(updated);
        showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

