@namespace sv_0974923068dc45e09f12567adabe83ef.Components.Pages.Settings
@using sv_0974923068dc45e09f12567adabe83ef.Services

<div class="settings-section">
    <h3>Security</h3>

    @if (Settings is not null)
    {
        <!-- Change Password Panel -->
        <div class="card mb-4">
            <div class="card-header d-flex justify-content-between align-items-center"
                 style="cursor: pointer" @onclick="() => passwordExpanded = !passwordExpanded">
                <span>Change Password</span>
                <span>@(passwordExpanded ? "▼" : "▶")</span>
            </div>
            @if (passwordExpanded)
            {
                <div class="card-body">
                    <div class="mb-2">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="currentPassword" />
                    </div>
                    <div class="mb-2">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm Password</label>
                        <input type="password" class="form-control" @bind="confirmPassword" />
                    </div>
                    @if (!string.IsNullOrEmpty(passwordError))
                    {
                        <div class="alert alert-danger">@passwordError</div>
                    }
                    @if (passwordSuccess)
                    {
                        <div class="alert alert-success">Password updated successfully!</div>
                    }
                    <button class="btn btn-primary" @onclick="ChangePasswordAsync">Update Password</button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="card mb-4">
            <div class="card-body">
                <div class="d-flex align-items-center justify-content-between">
                    <div>
                        <h5 class="mb-1">Two-Factor Authentication</h5>
                        <span class="badge @(Settings.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                            @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" checked="@Settings.TwoFactorEnabled"
                               @onchange="Toggle2FA" />
                    </div>
                </div>
                @if (Settings.LastPasswordChange.HasValue)
                {
                    <p class="text-muted small mt-2 mb-0">
                        Last password change: @Settings.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                    </p>
                }
            </div>
        </div>

        <!-- Active Sessions -->
        <div class="card mb-4">
            <div class="card-header">Active Sessions</div>
            <div class="card-body p-0">
                <table class="table table-hover mb-0">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in Settings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (session.Id != CurrentSessionId)
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="badge bg-info">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (sessionToRevoke is not null)
        {
            <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
                <div class="modal-dialog">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">Revoke Session</h5>
                            <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                        </div>
                        <div class="modal-body">
                            <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> from <strong>@sessionToRevoke.Location</strong>?</p>
                        </div>
                        <div class="modal-footer">
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                            <button class="btn btn-danger" @onclick="ConfirmRevokeAsync">Revoke Session</button>
                        </div>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string current, string newPw)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter] public EventCallback<bool> OnToggle2FA { get; set; }

    private string CurrentSessionId => Settings?.Sessions.FirstOrDefault()?.Id ?? "";

    private bool passwordExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private bool passwordSuccess;

    private ActiveSession? sessionToRevoke;

    private async Task ChangePasswordAsync()
    {
        passwordError = null;
        passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All fields are required.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((currentPassword, newPassword));
        passwordSuccess = true;
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
    }

    private async Task Toggle2FA(ChangeEventArgs e)
    {
        var enabled = (bool)e.Value!;
        await OnToggle2FA.InvokeAsync(enabled);
    }

    private void PromptRevoke(ActiveSession session) => sessionToRevoke = session;
    private void CancelRevoke() => sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(sessionToRevoke.Id);
            sessionToRevoke = null;
        }
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

