    {
        var updated = new UserProfile(editDisplayName, editEmail, editDisplayAvatarUrl, editBio);
        await OnSave.InvokeAsync(updated);
        showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void Discard()
    {
        LoadFromProfile();
        showSuccess = false;
    }
}

