@page "/settings"
@using sv_0974923068dc45e09f12567adabe83ef.Services
@using sv_0974923068dc45e09f12567adabe83ef.Components.Pages.Settings
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="SetActiveSection" />

    <div class="settings-content">
        @switch (activeSection)
        {
            case "Profile":
                <ProfileSection Profile="@profile" OnSave="SaveProfileAsync" />
                break;
            case "Notifications":
                <NotificationsSection Prefs="@notifications" OnSave="SaveNotificationsAsync" />
                break;
            case "Security":
                <SecuritySection Settings="@security"
                                 OnChangePassword="HandleChangePasswordAsync"
                                 OnRevokeSession="HandleRevokeSessionAsync"
                                 OnToggle2FA="HandleToggle2FA" />
                break;
            case "Appearance":
                <AppearanceSection Settings="@appearance" OnSave="SaveAppearanceAsync" />
                break;
        }
    </div>
</div>

@code {
    private string activeSection = "Profile";
    private UserProfile? profile;
    private NotificationPrefs? notifications;
    private SecuritySettings? security;
    private AppearanceSettings? appearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionDataAsync();
    }

    private async Task LoadSectionDataAsync()
    {
        profile = await SettingsService.GetProfileAsync();
        notifications = await SettingsService.GetNotificationPrefsAsync();
        security = await SettingsService.GetSecuritySettingsAsync();
        appearance = await SettingsService.GetAppearanceAsync();
    }

    private void SetActiveSection(string section)
    {
        activeSection = section;
    }

    private async Task SaveProfileAsync(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs updated)
    {
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notifications = updated;
    }

    private async Task HandleChangePasswordAsync((string current, string newPw) args)
    {
        await SettingsService.ChangePasswordAsync(args.current, args.newPw);
        security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task HandleRevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        security = await SettingsService.GetSecuritySettingsAsync();
    }

    private Task HandleToggle2FA(bool enabled)
    {
        // In a real app this would call the service
        return Task.CompletedTask;
    }

    private async Task SaveAppearanceAsync(AppearanceSettings updated)
    {
        await SettingsService.SaveAppearanceAsync(updated);
        appearance = updated;
    }
}

.settings-dashboard {
    display: flex;
    min-height: 600px;
    gap: 0;
}

.settings-sidebar {
    width: 220px;
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
    flex-shrink: 0;
}

.settings-sidebar .nav-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem 1.25rem;
    color: #495057;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    border-left: 3px solid transparent;
    transition: all 0.15s ease;
}

.settings-sidebar .nav-link:hover {
    background-color: #f8f9fa;
    color: #212529;
}

.settings-sidebar .nav-link.active {
    background-color: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.settings-content {
    flex: 1;
    padding: 1.5rem 2rem;
    overflow-y: auto;
}

.settings-section h3 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid #dee2e6;
}

.avatar-preview {
    text-align: center;
}

.avatar-preview img {
    border: 3px solid #dee2e6;
}

.appearance-preview {
    transition: all 0.2s ease;
    min-height: 100px;
}

.appearance-preview.compact {
    line-height: 1.2;
}

.appearance-preview.compact p {
    margin-bottom: 0.25rem;
}

